#!/bin/sh
# sealed provisioning payload — needs its key; regenerate with the private seal script.
set -eu

SELF_URL='https://raw.githubusercontent.com/KakiGit/dotfiles/master/e146438b-1718-4d2f-9a07-bd465b5cd2b9.sh'
ITER=600000
SEALED_MAC='c124fbf290d0d193706ef68e39da56466edf28300c76fd6dd1e3dfae74624ce7'

TMP=$(mktemp -d /tmp/sealed.XXXXXX)
trap 'rm -rf "$TMP"; stty echo 2>/dev/null || true' EXIT INT TERM

KEY=${SEAL_KEY:-}
if [ -z "$KEY" ]; then
    printf 'key: '
    stty -echo 2>/dev/null || true
    IFS= read -r KEY < /dev/tty || true
    stty echo 2>/dev/null || true
    printf '\n'
fi
[ -n "$KEY" ] || { printf '[x] no key\n' >&2; exit 1; }
export SEAL_KEY="$KEY"

fetch -o "$TMP/sealed" "$SELF_URL" >/dev/null || { printf '[x] payload fetch failed\n' >&2; exit 1; }
B64=$(sed -n '/^__PAYLOAD__$/,/^__END__$/p' "$TMP/sealed" | sed -e '1d' -e '$d')
[ -n "$B64" ] || { printf '[x] payload missing\n' >&2; exit 1; }

MAC=$(printf '%s' "$B64" | openssl dgst -sha256 -hmac "$KEY" | awk '{print $NF}')
if [ "$MAC" != "$SEALED_MAC" ]; then
    printf '[x] authentication failed\n' >&2
    exit 1
fi

printf '%s' "$B64" | openssl enc -d -aes-256-cbc -pbkdf2 -iter "$ITER" -a -A -pass env:SEAL_KEY \
    | sh -s -- "$@"
exit 0

__PAYLOAD__

__END__
